/* Confidential briefs come from authenticated RPCs, not the public application bundle. */
window.AssemblyRooms=(()=>{
 const names={k:'Kitala',n:'Nordland',m:'Meridia',p:'Pelagia',s:'Solenne',a:'Aridia',v:'Verdan',e:'Estara',Chair:'Professor / Chair'};
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const modal=document.createElement('dialog');modal.className='live-room-dialog';modal.setAttribute('aria-label','Live classroom practice');document.body.append(modal);
 let client,room=null,catalog=[],classes=[],roster=[],professor=false,poller,clock,offset=0,epoch=0,polling=false,mutating=false,draftVersion=0,reportVersion=0,solo=false,rooms=[];
 const el=id=>modal.querySelector('#'+id),btn=(text,action,value='',kind='secondary')=>`<button type="button" class="${kind}" data-live="${action}" data-value="${esc(value)}">${esc(text)}</button>`;
 async function rpc(name,args={}){const {data,error}=await client.rpc(name,args);if(error)throw error;return data;}
 function error(e){if(el('roomStatus')){el('roomStatus').textContent=['PGRST202','42883'].includes(e.code)?'This upgrade needs its database setup. Run the supplied classroom upgrade SQL in Supabase, then reopen this page.':e.message||'Connection interrupted. Your unsent text remains here.';el('roomStatus').className='account-status error';}}
 function message(s){if(el('roomStatus')){el('roomStatus').textContent=s;el('roomStatus').className='account-status';}}
 function stop(){clearInterval(poller);clearInterval(clock);epoch++;polling=false;}
 function unsent(){return Boolean(el('roomReport')&&el('roomReport').value!==(room?.report_text||'')||el('roomMessage')?.value||el('roomExplanation')?.value||el('roomInject')?.value||el('overviewEventText')?.value||el('practiceOpening')?.value||el('practiceResponse')?.value||el('roomDraft')&&!el('roomDraft').readOnly&&el('roomDraft').value!==room?.draft);}
 function close(){if(unsent()&&!confirm('Close this view? Unsent text will be discarded; sent classroom work remains saved.'))return false;stop();modal.close();document.body.classList.remove('live-active');return true;}
 modal.addEventListener('cancel',e=>{e.preventDefault();close()});
 function shell(html){modal.innerHTML='<div class="live-top">'+btn('Return to assembly','close')+'<span class="eyebrow">ASSEMBLY / '+(solo?'SOLO PRACTICE':'LIVE CLASSROOM PRACTICE')+'</span></div>'+html+'<p id="roomStatus" role="status" class="account-status"></p>';}
 async function open(){stop();room=null;solo=false;client=AssemblyAccount.connection();shell('<h2>Live classroom practice</h2><p>Loading your rooms...</p>');if(!modal.open)modal.showModal();document.body.classList.add('live-active');try{await dashboard()}catch(e){error(e)}}
 async function context(){const results=await Promise.all([rpc('assembly_topic_catalog'),client.from('assembly_classes').select('id,title,teacher_id'),client.auth.getUser(),client.from('assembly_roles').select('role').maybeSingle()]);for(const result of results.slice(1))if(result.error)throw result.error;catalog=results[0];const uid=results[2].data.user?.id;classes=(results[1].data||[]).map(c=>({...c,teacher:c.teacher_id===uid}));professor=results[3].data?.role==='professor';}
 function safeLink(url){try{const u=new URL(url);return u.protocol==='https:'?u.href:'#'}catch{return '#'}}
 function packet(t){const p=t?.packet||{};return '<p>'+esc(p.background||t?.summary||'')+'</p><p><b>Negotiation task:</b> '+esc(p.objective||'Review the shared policy recommendations.')+'</p>'+(p.source?'<a href="'+esc(safeLink(p.source))+'" target="_blank" rel="noopener">'+esc(p.source_label||'WHO background reading')+'</a>':'')+'<p class="micro-note">'+esc(p.scope||'Fictional teaching exercise; not an official WHO negotiation.')+'</p>';}
 function brief(b){if(!b)return '<p>Your professor has not assigned your role yet.</p>';const labels={background:'Country background',priorities:'Priorities',constraints:'Constraints and red lines',evidence:'Evidence and assumptions',authority:'Authority and limits',leverage:'Negotiating resources',possible_concessions:'Possible concessions',opening_task:'Opening statement',implementation_task:'Implementation task'};return '<h3>'+esc(b.name)+'</h3>'+Object.entries(labels).map(([k,l])=>'<section class="brief-section"><h4>'+l+'</h4><p>'+esc(b[k])+'</p></section>').join('')+'<p class="micro-note">'+esc(b.confidential_note)+'</p>';}
 function topicPreview(){const t=catalog.find(t=>t.id===el('createTopic')?.value);if(t)el('topicPreview').innerHTML=packet(t)+'<details><summary>Review confidential role briefs</summary>'+Object.values(t.roles||{}).map(b=>'<details><summary>'+esc(b.name)+'</summary>'+brief(b)+'</details>').join('')+'</details>';}
 async function dashboard(){stop();room=null;solo=false;await context();const own=classes.filter(c=>c.teacher);rooms=await rpc('assembly_live_list');shell('<h2>'+(professor?'Professor classroom dashboard':'Your live classrooms')+'</h2><p>'+(professor?'Manage topics, roles, timers and unexpected events across your rooms.':'Join from your own device. Your professor assigns your delegation; your private briefing appears in that room.')+'</p>'+(professor?'<details class="room-create"><summary>Create a negotiation room</summary>'+(own.length?'<form id="roomCreate"><div class="create-grid"><label>Classroom<select name="classId">'+own.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.title)+'</option>').join('')+'</select></label><label>Room title<input name="title" required maxlength="100" placeholder="Group 1"></label><label>Health issue<select id="createTopic" name="topic">'+catalog.map(t=>'<option value="'+esc(t.id)+'">'+esc(t.title)+'</option>').join('')+'</select></label><label>Students<select name="capacity">'+[4,5,6,7,8].map(n=>'<option>'+n+'</option>').join('')+'</select></label><label>Minutes<input name="minutes" type="number" min="1" max="180" value="30" required></label></div><div id="topicPreview"></div><button class="primary" type="submit">Create room</button></form>':'<p>Create a classroom in Account first so students can join using its code.</p>')+'</details>':'<p>Open the room named by your professor and click Join this room. You will receive a student number for that room.</p>')+'<div class="dashboard-toolbar"><label>Show classroom<select id="classFilter"><option value="">All classrooms</option>'+classes.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.title)+'</option>').join('')+'</select></label>'+btn('Refresh overview','dashboard')+'</div><div id="roomCards"></div>');if(professor){const box=document.createElement('section');box.id='dashboardEvent';box.className='event-inject';box.hidden=true;box.innerHTML='<h3>Send an unexpected event</h3><form id="overviewInject"><input name="roomId" type="hidden"><p id="overviewRoomName"></p><label>Event<textarea id="overviewEventText" name="event" maxlength="1500" required></textarea></label><button class="primary" type="submit">Send to this room</button></form>';el('roomCards').after(box);}if(el('topicPreview'))topicPreview();renderCards();poller=setInterval(pollDashboard,5000);clock=setInterval(tick,1000);}
 function renderCards(){const filter=el('classFilter')?.value||'';el('roomCards').innerHTML=rooms.filter(r=>!filter||r.class_id===filter).map(r=>'<article class="room-overview"><div><span class="eyebrow">'+esc(r.class_title)+'</span><h3>'+esc(r.title)+'</h3><p>'+esc(r.topic)+'</p></div><div class="room-metrics"><span>'+r.seats+' / '+r.capacity+' students</span><span>'+esc(r.phase)+'</span><span data-clock-end="'+esc(r.timer_end||'')+'" data-clock-remaining="'+esc(r.timer_remaining??'')+'">'+(r.phase==='lobby'?'Not started':'')+'</span>'+(r.teacher?'<span>'+r.responded+' responses / '+r.objections+' objections</span>':'<span>'+(r.mine?'Your assigned room':'Awaiting assignment')+'</span>')+'</div>'+btn(r.teacher?'Manage room':r.mine?'Enter classroom':'Open room','room',r.id,'primary')+(r.teacher&&r.phase!=='adopted'?'<div>'+ (r.phase==='lobby'?btn('Start room','overviewStart',r.id):'')+btn('Unexpected event','overviewEvent',r.id)+'</div>':'')+'</article>').join('')||'<p>No rooms in this classroom yet.</p>';if(rooms[0]?.server_now)offset=Date.parse(rooms[0].server_now)-Date.now();tick();}
 async function pollDashboard(){if(polling||mutating||room||!modal.open||solo)return;polling=true;const ticket=epoch;try{const next=await rpc('assembly_live_list');if(ticket===epoch){rooms=next;renderCards();}}catch(e){if(ticket===epoch)error(e)}finally{if(ticket===epoch)polling=false}}
 function tick(){for(const node of modal.querySelectorAll('[data-clock-end]')){const end=node.dataset.clockEnd,remaining=node.dataset.clockRemaining;if(!end&&remaining===''){if(!node.textContent)node.textContent='Not started';continue}const secs=end?Math.max(0,Math.ceil((Date.parse(end)-Date.now()-offset)/1000)):Number(remaining);node.textContent=(end?'':'Paused / ')+Math.floor(secs/60)+':'+String(secs%60).padStart(2,'0')+(secs===0?' / time elapsed':'');}}
 async function enter(id){stop();room=await rpc('assembly_live_snapshot',{target_room:id});roster=room.teacher?await rpc('assembly_room_roster',{target_room:room.id}):[];offset=Date.parse(room.server_now)-Date.now();renderRoom();poller=setInterval(pollRoom,3500);clock=setInterval(tick,1000);}
 function fields(){return Object.fromEntries([...modal.querySelectorAll('textarea')].map(n=>[n.id,n.value]));}
 function assignment(){
 const slots=Array.from({length:room.capacity},(_,i)=>({number:i+1,student:roster.find(s=>s.number===i+1)}));
 const roleFor=student=>student&&Object.entries(room.assigned||{}).find(([,uid])=>uid===student.id)?.[0];
 return '<p>Only the professor assigns roles. Choose a student, then click Assign. All '+room.capacity+' numbered places are shown; students must join this room before receiving a role.</p><ul>'+slots.map(({number,student})=>'<li>Student '+number+' &mdash; '+(roleFor(student)?esc(names[roleFor(student)]):student?'Joined; no role assigned':'Not joined yet')+'</li>').join('')+'</ul>'+btn('Refresh student list','roster')+(Object.keys(room.assigned||{}).length?btn('Clear all role assignments','clearAssignments'):'')+Object.entries(room.all_briefs||{}).map(([id,b])=>'<div class="assignment-row"><b>'+esc(b.name)+'</b><p>Current assignment: '+esc(roster.find(s=>s.id===room.assigned?.[id])?.name||'None')+'</p><select id="assign-'+id+'" aria-label="Student for '+esc(b.name)+'"><option value="">Choose a student</option>'+slots.map(({number,student})=>'<option value="'+esc(student?.id||'')+'" '+(!student?'disabled':'')+'>Student '+number+(student?(roleFor(student)?' (currently '+esc(names[roleFor(student)])+')':' (unassigned)'):' (not joined yet)')+'</option>').join('')+'</select>'+btn('Assign','assign',id)+(room.assigned?.[id]?btn('Release role','release',id):'')+'<details><summary>Read confidential role</summary>'+brief(b)+'</details></div>').join('');
 }
 function renderRoom(saved={},priorVersion=null){const r=room,read=r.teacher||r.role,locked=r.phase==='adopted'||r.teaching_session?.stage==='finished';draftVersion=r.draft_version;if(!Object.hasOwn(saved,'roomReport'))reportVersion=r.report_version||1;shell((r.student_number?'<p class="note">You are Student '+r.student_number+(r.role?' / '+esc(names[r.role]):' / awaiting your role')+'</p>':'')+'<div id="sessionRoomBanner"></div><div class="room-heading"><div><span class="eyebrow">'+esc(r.topic)+'</span><h2>'+esc(r.title)+'</h2></div><div class="room-clock" data-clock-end="'+esc(r.timer_end||'')+'" data-clock-remaining="'+esc(r.timer_remaining??'')+'">'+(r.phase==='lobby'?'Not started':'')+'</div></div><nav class="room-flow" aria-label="Simulation stage">'+['lobby','consultation','committee','plenary','adopted'].map(p=>'<span class="'+(r.phase===p?'active':'')+'">'+p+'</span>').join('')+'</nav><div class="room-toolbar">'+(r.prepared?btn('Teaching session lobby','mainLobby'):btn(professor?'All classrooms':'My classrooms','dashboard'))+'<span id="roomSync" role="status">Updates arrive automatically.</span></div>'+(read?'<div class="room-columns"><aside class="room-sidebar"><details open><summary>'+(r.teacher?'Scenario and role briefs':'My private role brief')+'</summary>'+(r.teacher?packet({packet:r.packet})+Object.values(r.all_briefs||{}).map(b=>'<details><summary>'+esc(b.name)+'</summary>'+brief(b)+'</details>').join(''):brief(r.brief))+'</details>'+(!r.teacher?'<details><summary>Shared scenario background</summary>'+packet({packet:r.packet})+'</details>':'')+(r.teacher&&!r.prepared&&r.phase==='lobby'?'<details open><summary>Assign students to roles</summary>'+assignment()+'</details>':'')+(r.teacher&&!locked?'<details open><summary>Professor controls</summary>'+(r.prepared&&r.phase==='lobby'?'':btn({lobby:'Start simulation and timer',consultation:'Submit to Committee A',committee:'Send to closing plenary',plenary:'Confirm adoption'}[r.phase],'advance','','primary'))+(['committee','plenary'].includes(r.phase)?btn('Return to consultation','reopen'):'')+(r.prepared?'<p>Control the shared teaching timer in the main lobby.</p>':r.phase!=='lobby'?btn(r.timer_end?'Pause timer':'Resume timer',r.timer_end?'timer_pause':'timer_resume')+btn('Add 5 minutes','timer_extend'):'<p>Planned duration: '+Math.round(r.duration_seconds/60)+' minutes.</p>')+'<p class="micro-note">The clock guides discussion; it never adopts or rejects the resolution automatically.</p></details><details><summary>Add an unexpected event</summary><label>Suggested event<select id="injectTemplate"><option value="">Write a custom event</option>'+(r.inject_templates||[]).map((t,i)=>'<option value="'+i+'">'+esc(t.slice(0,85))+'</option>').join('')+'</select></label><textarea id="roomInject" maxlength="1500" placeholder="Describe the event and ask delegates to reconsider..."></textarea>'+btn('Send event to this classroom','inject','','primary')+'<p class="micro-note">An event during committee or plenary reopens consultation and clears positions.</p></details>':'')+'</aside><section class="room-main"><div id="roomEventAlert" role="status"></div>'+(r.prepared?'<details open><summary>Shared classroom report</summary><p>Record the agreement or unresolved differences, implementation responsibilities, evidence, and lessons learned. Editing opens during the 15-minute report stage.</p><textarea id="roomReport" maxlength="15000" '+(r.teaching_session?.stage==='report'?'':'readonly')+'>'+esc(r.report_text||'')+'</textarea>'+btn('Load latest report','loadReport')+(r.teaching_session?.stage==='report'?btn('Save report for classroom','saveReport','','primary'):'')+'</details>':'')+'<details open><summary>Classroom discussion</summary><p>Speak together in class and record ideas here. Messages are shared only with this room and the professor. Audio calls are not provided.</p><div id="liveMessages" class="room-log"></div>'+(!locked?'<label>Your statement, question or offer<textarea id="roomMessage" maxlength="1000" placeholder="Our delegation proposes..."></textarea></label>'+btn('Send to classroom','message','','primary'):'')+'</details><details><summary>Shared resolution / draft '+r.draft_version+'</summary><p id="draftUpdate" class="note" hidden></p>'+btn('Load latest shared draft','loadDraft')+'<textarea id="roomDraft" maxlength="6000" '+(locked||r.phase!=='consultation'?'readonly':'')+'>'+esc(r.draft)+'</textarea>'+(!locked&&r.phase==='consultation'?btn('Circulate this wording','draft','','primary'):'')+'</details><details open><summary>Delegation positions</summary><div id="liveResponses"></div>'+(!locked&&!r.teacher&&['committee','plenary'].includes(r.phase)?'<label>Explanation (optional)<textarea id="roomExplanation" maxlength="600"></textarea></label>'+btn('No objection','respond','no_objection','primary')+btn('Object / revise the text','respond','object'):'')+'</details>'+(locked?'<p class="note">This classroom record is read-only.</p>'+btn('Download final agreement (PDF)','download','','primary'):'')+'<details><summary>Full negotiation record</summary><div id="fullRoomLog" class="room-log"></div></details></section></div>':(r.student_number?'<p class="note">You have joined this room. Your professor will assign your role; your private briefing will appear automatically.</p>':'<p>Join only the room your professor has specified. Your student number belongs to this room.</p>'+btn('Join this room','enroll','','primary'))));for(const [id,value] of Object.entries(saved))if(el(id))el(id).value=value;if(saved.roomDraft&&saved.roomDraft!==r.draft){draftVersion=r.phase==='consultation'?(priorVersion??-1):-1;if(draftVersion!==r.draft_version&&el('draftUpdate')){el('draftUpdate').hidden=false;el('draftUpdate').textContent='Your unsent wording is retained. Copy it if needed, then load the current shared draft before circulating or recording a position.';}}renderActivity();sessionBanner();tick();}
 function sessionBanner(){if(!room?.prepared||!el('sessionRoomBanner'))return;const t=room.teaching_session;if(!t)return;AssemblyWorkshop.observe(t);el('sessionRoomBanner').innerHTML='<p class="note">Teaching stage: '+esc(t.stage)+' '+btn('Return to main lobby','mainLobby')+'</p><p>Participants: '+(room.participants||[]).map(p=>esc(p.name)+' ('+esc(p.role_name)+')').join(', ')+'</p>'+t.broadcasts.slice(-3).map(b=>'<p class="note"><strong>Professor announcement:</strong> '+esc(b.text)+'</p>').join('')+(['report','debrief','finished'].includes(t.stage)?btn('Download classroom report (PDF)','workingReport','','primary'):'');for(const n of modal.querySelectorAll('[data-clock-end]')){n.dataset.clockEnd=t.ends||'';n.dataset.clockRemaining=t.remaining??'';}}
 function workingReport(){const r={live:true,title:room.title,id:'REPORT-'+room.id.slice(0,8),date:new Date().toISOString(),mode:'live',roster:(room.participants||[]).map(p=>p.name+' / '+p.role_name).join('; '),rows:[],sections:[{title:'Topic',text:room.topic},{title:'Decision status',text:room.phase==='adopted'?'Adopted without objection.':'Working classroom report. Formal adoption has not been recorded.'},{title:'Classroom report',text:room.report_text||'No report text saved.'},{title:'Shared policy text',text:room.draft||''},{title:'Discussion and events',text:room.events.map(e=>e.actor+': '+e.text).join('\n')},{title:'Scope',text:'Independent educational simulation. Private role instructions excluded.'}]};const u=URL.createObjectURL(new Blob([Agreement.pdf(r)],{type:'application/pdf'}));const a=document.createElement('a');a.href=u;a.download=r.id+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 function renderActivity(){if(!el('liveMessages'))return;const events=room.events||[];el('liveMessages').innerHTML=events.filter(e=>['message','inject'].includes(e.kind)).slice(-50).map(e=>'<article class="'+(e.kind==='inject'?'event-inject':'')+'"><b>'+esc(names[e.actor]||e.actor)+(e.kind==='inject'?' / Unexpected event':'')+'</b><p>'+esc(e.text)+'</p><small>'+esc(new Date(e.at).toLocaleTimeString())+'</small></article>').join('')||'<p>No messages yet. Share your national priorities.</p>';el('liveResponses').innerHTML=room.seats.map(id=>'<p><b>'+esc(names[id])+'</b>: '+esc(room.responses[id]?.position?.replace('_',' ')||'No position recorded')+(room.responses[id]?.explanation?' - '+esc(room.responses[id].explanation):'')+'</p>').join('');el('fullRoomLog').innerHTML=events.slice().reverse().map(e=>'<article><b>'+esc(names[e.actor]||e.actor)+' / '+esc(e.kind)+'</b><p>'+esc(e.text)+'</p></article>').join('');const inject=events.filter(e=>e.kind==='inject').at(-1);el('roomEventAlert').innerHTML=inject?'<div class="event-inject"><b>Latest unexpected event</b><p>'+esc(inject.text)+'</p></div>':'';}
 function acceptUpdate(update){const prev=room,saved=fields(),priorVersion=draftVersion;offset=Date.parse(update.server_now)-Date.now();room=update;if(prev.role!==update.role){renderRoom();return}if(prev.phase!==update.phase||prev.teaching_session?.stage!==update.teaching_session?.stage){if(saved.roomDraft===prev.draft)delete saved.roomDraft;renderRoom(saved,priorVersion);message('The room moved to '+room.phase+'. Review the updated instructions.');return}if(room.draft_version!==draftVersion&&el('draftUpdate')){el('draftUpdate').hidden=false;el('draftUpdate').textContent='New shared wording is available. Load and review it before editing or recording a position. Your unsent wording has not been overwritten.';}renderActivity();sessionBanner();for(const n of modal.querySelectorAll('[data-clock-end]')){n.dataset.clockEnd=room.teaching_session?.ends||room.timer_end||'';n.dataset.clockRemaining=room.teaching_session?.remaining??room.timer_remaining??'';}tick();if(el('roomSync'))el('roomSync').textContent='Connected / classroom activity updated.';}
 async function pollRoom(){if(polling||mutating||!room||!modal.open)return;const ticket=epoch,id=room.id;polling=true;try{const next=await rpc('assembly_live_snapshot',{target_room:id});if(ticket===epoch&&id===room?.id)acceptUpdate(next)}catch(e){if(ticket===epoch)error(e)}finally{if(ticket===epoch)polling=false}}
 async function perform(kind,payload={},clear=[]){mutating=true;const saved=fields(),priorVersion=draftVersion,ticket=epoch,id=room.id;try{const next=await rpc('assembly_live_action',{target_room:id,action_name:kind,payload});if(ticket!==epoch||room?.id!==id||!modal.open)return;clear.forEach(id=>delete saved[id]);if(saved.roomDraft===room.draft)delete saved.roomDraft;room=next;renderRoom(saved,priorVersion);}finally{mutating=false}}
 function download(){if(room.phase!=='adopted')return;const r={live:true,title:room.title,id:'ROOM-'+room.id.slice(0,8),date:new Date().toISOString(),mode:'live',roster:room.seats.map(id=>names[id]).join('; ')+'; Professor / Chair',rows:[],sections:[{title:'Health issue',text:room.topic},{title:'Decision',text:'Adopted without objection by assigned student delegations after Committee A and closing-plenary consideration. Independent fictional educational exercise.'},{title:'Adopted resolution',text:room.draft},{title:'Final positions',text:room.seats.map(id=>names[id]+': '+room.responses[id].position+'; '+(room.responses[id].explanation||'No explanation.')).join('\n')},{title:'Discussion, unexpected events and draft record',text:room.events.map(e=>(names[e.actor]||e.actor)+' / '+e.kind+' / '+e.phase+' / '+e.at+': '+e.text).join('\n')},{title:'Scope',text:'Human students on separate devices. No AI votes. Confidential role briefs are excluded from this shared report. Policy recommendations are not proof of implementation.'}]};const url=URL.createObjectURL(new Blob([Agreement.pdf(r)],{type:'application/pdf'}));const a=document.createElement('a');a.href=url;a.download=r.id+'-agreement.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 async function soloTopics(){stop();room=null;solo=true;client=AssemblyAccount.connection();shell('<h2>Solo practice</h2><p>Loading topics...</p>');if(!modal.open)modal.showModal();try{catalog=await rpc('assembly_topic_catalog');shell('<h2>Solo practice</h2><p>Prepare for your live classroom. Public practice prompts do not reveal confidential classroom role instructions.</p>'+btn('Guided audiovisual vaccine exercise','guided','','primary')+catalog.map(t=>'<article class="account-card"><h3>'+esc(t.title)+'</h3><p>'+esc(t.summary)+'</p>'+btn('Practice this topic','soloTopic',t.id)+'</article>').join(''));}catch(e){shell('<h2>Solo practice</h2>'+btn('Guided audiovisual vaccine exercise','guided','','primary'));error(e)}}
 function soloTopic(id){const t=catalog.find(t=>t.id===id);if(!t)return;shell('<h2>'+esc(t.title)+'</h2>'+packet(t)+'<p>Choose a fictional national perspective and rehearse a priority, evidence and compromise. This is self-directed preparation, not live AI negotiation.</p><label>Opening statement<textarea id="practiceOpening" maxlength="1500" placeholder="Our delegation prioritizes... because... We propose..."></textarea></label><label>Possible objection and your response<textarea id="practiceResponse" maxlength="1500" placeholder="Another delegation might object that... We could respond by..."></textarea></label><label>Implementation paragraph<textarea id="practiceDraft" maxlength="2000">'+esc(t.zero_draft)+'</textarea></label>'+btn('Review my preparation','soloReview')+btn('Download practice notes','soloDownload',id,'primary')+'<div id="practiceFeedback" role="status"></div><p class="micro-note">Notes stay in this page until downloaded; they are not submitted.</p>');}
 modal.addEventListener('change',e=>{if(e.target.id==='createTopic')topicPreview();if(e.target.id==='classFilter')renderCards();if(e.target.id==='injectTemplate'&&e.target.value!=='')el('roomInject').value=room.inject_templates[Number(e.target.value)]||'';});
 modal.addEventListener('click',async e=>{const b=e.target.closest('[data-live]');if(!b)return;const kind=b.dataset.live,value=b.dataset.value;b.disabled=true;try{
  if(kind==='loadReport'){if(el('roomReport').value!==(room.report_text||'')&&!confirm('Replace your editor with the latest saved report? Copy unsaved changes first.'))return;el('roomReport').value=room.report_text||'';reportVersion=room.report_version;return}if(kind==='saveReport'){const text=el('roomReport').value,ticket=epoch,id=room.id;const next=await rpc('assembly_save_room_report',{target_room:room.id,report_body:text,expected_version:reportVersion});if(ticket!==epoch||room?.id!==id)return;room=next;reportVersion=next.report_version;message('Classroom report saved.');return}if(kind==='workingReport'){workingReport();return}if(kind==='mainLobby'){if(close())await AssemblyWorkshop.lobby(room.class_id);return}if(kind==='close'){close();return}if(kind==='dashboard'){if(unsent()&&!confirm('Return to the overview? Unsent text will be discarded.'))return;await dashboard();return}if(kind==='room'){await enter(value);return}if(kind==='overviewEvent'){el('dashboardEvent').hidden=false;el('overviewInject').elements.roomId.value=value;el('overviewRoomName').textContent=rooms.find(r=>r.id===value)?.title||'';el('dashboardEvent').scrollIntoView({block:'nearest'});return}if(kind==='overviewStart'){const r=await rpc('assembly_live_snapshot',{target_room:value});await rpc('assembly_live_action',{target_room:value,action_name:'advance',payload:{revision:r.revision}});rooms=await rpc('assembly_live_list');renderCards();return}
  if(kind==='guided'){if(close())Chamber.setup('solo');return}if(kind==='soloTopic'){soloTopic(value);return}
  if(kind==='soloReview'){el('practiceFeedback').innerHTML='<h3>Review checklist</h3><ul><li>Separate WHO evidence from fictional national assumptions.</li><li>Explain what you can concede and what you need in return.</li><li>Name an implementation owner, timing and progress indicator.</li><li>Explain why another delegation could accept your wording.</li></ul>';return}
  if(kind==='soloDownload'){const text=['ASSEMBLY / SOLO PREPARATION',catalog.find(t=>t.id===value)?.title,el('practiceOpening').value,el('practiceResponse').value,el('practiceDraft').value].join('\n\n');const u=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=u;a.download='assembly-practice.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);return}
  if(kind==='enroll'){await rpc('assembly_room_enroll',{target_room:room.id});await enter(room.id);return}if(kind==='download'){download();return}if(kind==='roster'){roster=await rpc('assembly_room_roster',{target_room:room.id});renderRoom(fields());return}
  if(kind==='clearAssignments'){if(confirm('Clear every role assignment in this room? Students keep their numbers and you can assign roles again.'))await perform('clear_assignments');return}if(kind==='assign'){const student=el('assign-'+value).value;if(!student)throw Error('Choose a joined student first.');const old=Object.entries(room.assigned||{}).find(([role,uid])=>uid===student&&role!==value)?.[0];if((old||room.assigned?.[value]&&room.assigned[value]!==student)&&!confirm('Assign this student to '+names[value]+'? Their previous role will be released, and any student currently in this role will become unassigned.'))return;await perform(old?'reassign':'assign',{role:value,student});return}if(kind==='release'){await perform('release',{role:value});return}
  if(kind==='message'){await perform('message',{text:el('roomMessage').value},['roomMessage']);return}
  if(kind==='loadDraft'){if(el('roomDraft').value!==room.draft&&!confirm('Replace the editor with the current shared draft? Copy any unsent wording you want to keep first.'))return;el('roomDraft').value=room.draft;draftVersion=room.draft_version;el('draftUpdate').hidden=true;return}
  if(kind==='draft'){if(draftVersion!==room.draft_version)throw Error('Load the current shared draft before circulating a revision.');await perform('draft',{text:el('roomDraft').value,revision:room.revision},['roomDraft']);return}
  if(kind==='respond'){if(draftVersion!==room.draft_version)throw Error('Review the latest shared draft before recording your position.');await perform('respond',{position:value,explanation:el('roomExplanation').value,phase:room.phase,draft_version:room.draft_version},['roomExplanation']);return}
  if(kind==='inject'){await perform('inject',{text:el('roomInject').value},['roomInject']);return}
  if(kind==='advance')await perform('advance',{revision:room.revision});if(kind==='reopen')await perform('reopen');if(kind==='timer_pause'||kind==='timer_resume')await perform(kind);if(kind==='timer_extend')await perform(kind,{minutes:5});
 }catch(err){error(err)}finally{b.disabled=false}});
 modal.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button[type="submit"]');if(b)b.disabled=true;try{if(f.id==='overviewInject'){await rpc('assembly_live_action',{target_room:f.elements.roomId.value,action_name:'inject',payload:{text:f.elements.event.value}});f.elements.event.value='';el('dashboardEvent').hidden=true;rooms=await rpc('assembly_live_list');renderCards();message('Unexpected event sent to the selected classroom.');}if(f.id==='studentRegister'){await rpc('assembly_live_register',{student_name:f.elements.name.value});message('Registered. Your professor can assign your role.');}if(f.id==='roomCreate'){const id=await rpc('assembly_live_create_v2',{target_class:f.elements.classId.value,room_title:f.elements.title.value,chosen_topic:f.elements.topic.value,student_capacity:Number(f.elements.capacity.value),minutes:Number(f.elements.minutes.value)});await enter(id)}}catch(err){error(err)}finally{if(b)b.disabled=false}});
 async function openRoom(id){client=AssemblyAccount.connection();await context();if(!modal.open)modal.showModal();document.body.classList.add('live-active');await enter(id);}
 return {open,soloTopics,openRoom};
})();
